"""Isolated paths for evidence generated by tests and browser checks."""

from __future__ import annotations

import os
from pathlib import Path


def artifact_path(relative_path: str) -> Path:
    """Return a test artifact path rooted outside the checkout by default."""
    relative = Path(relative_path)
    if relative.is_absolute() or ".." in relative.parts:
        raise ValueError("test artifact paths must stay within their artifact root")

    root = os.environ.get("HUTCH_TEST_ARTIFACTS_DIR")
    if root is None:
        raise RuntimeError("pytest must configure HUTCH_TEST_ARTIFACTS_DIR before collecting tests")
    return Path(root).expanduser() / relative


def repository_path(relative_path: str) -> Path:
    """Resolve an input/source path from the candidate checkout, independent of artifact storage."""
    relative = Path(relative_path)
    if relative.is_absolute() or ".." in relative.parts:
        raise ValueError("repository paths must stay within the candidate checkout")
    root = Path(__file__).resolve().parents[2]
    return root / relative
